settings = {}
plugin = None

for line_number, raw_line in enumerate(text.splitlines(), start=1):
    line = raw_line.strip()
    if not line or line.startswith("#"):
        continue

    key, separator, value_text = line.partition("=")
    if not separator:
        raise ValueError(f"invalid profile line {line_number}: expected 'key = value'")

    key = key.strip()
    if not key:
        raise ValueError(f"invalid profile line {line_number}: missing key")

    try:
        value = ast.literal_eval(value_text.strip())
    except (SyntaxError, ValueError) as exc:
        raise ValueError(f"invalid value for {key!r} on line {line_number}") from exc

    if key == "plugin":
        if not isinstance(value, str):
            raise ValueError(f"invalid plugin on line {line_number}: expected plugin name string")
        try:
            plugin = BUILTIN_PLUGINS[value]()
        except KeyError as exc:
            raise ValueError(f"unknown plugin {value!r} on line {line_number}") from exc
    else:
        settings[key] = value

return {"settings": settings, "plugin": plugin}
